    private static Formula V(string name) => F.Id(name);
    private static Formula D(long n) => new Formula.Number(n);
    private static Formula R => C("Real");
    private static Formula N => C("Nat");
    private static Formula Parenthesized(Formula x) => Seq(Open, x, Close);
    private static Formula P(Formula x) => Parenthesized(x);
    private static Formula C(string name, params Formula[] args)
    {
        var parts = new List<Formula>();
        foreach (var word in name.Split('.'))
        {
            if (parts.Count > 0) parts.Add(Dot);
            parts.Add(V(word));
        }
        return new Formula.Apply(Seq(Operatorname, Sp, Grp([.. parts])), [.. args]);
    }
    private static Formula All(string name, Formula type, Formula body) =>
        new Formula.Bind(FormulaQuantifier.ForAll, FormulaIdentifier.Create(name), type, body);
    private static Formula Lam(string name, Formula type, Formula body) =>
        Seq(LambdaLower, Sp, V(name), Colon, Sp, type, Comma, Sp, body);
    private static Formula Fr(Formula a, Formula b) => new Formula.Fraction(a,b);
    private static Formula Pow(Formula a, Formula b) => new Formula.Power(P(a),b);
    private static Formula Neg(Formula a) => new Formula.Negate(P(a));
    private static Formula Not(Formula a) => new Formula.Not(P(a));
    private static Formula Add(Formula a, Formula b) => new Formula.Binary(P(a),FormulaBinaryOperator.Add,P(b));
    private static Formula Sub(Formula a, Formula b) => new Formula.Binary(P(a),FormulaBinaryOperator.Subtract,P(b));
    private static Formula Mul(Formula a, Formula b) => new Formula.Binary(P(a),FormulaBinaryOperator.Multiply,P(b));
    private static Formula Eqn(Formula a, Formula b) => new Formula.Relation(a,FormulaRelationOperator.Equal,b);
    private static Formula Mem(Formula a, Formula b) => new Formula.Relation(a,FormulaRelationOperator.MemberOf,b);
    private static Formula Neq(Formula a, Formula b) => new Formula.Relation(a,FormulaRelationOperator.NotEqual,b);
    private static Formula Leq(Formula a, Formula b) => new Formula.Relation(a,FormulaRelationOperator.LessThanOrEqual,b);
    private static Formula Lt(Formula a, Formula b) => new Formula.Relation(a,FormulaRelationOperator.LessThan,b);
    private static Formula Imp(Formula a, Formula b) => new Formula.Logic(P(a),FormulaLogicOperator.Implies,P(b));
    private static Formula And(Formula a, Formula b) => new Formula.Logic(P(a),FormulaLogicOperator.And,P(b));
